testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Input e movimento",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

func run():
	var pos_x: float = 450.0
	return clamp(pos_x, 50.0, 500.0)
",
   "domanda": "Quanto vale il valore restituito da `run()`?",
   "spiegazione": "`pos_x` (450.0) è già compreso tra il minimo (50.0) e il massimo (500.0), quindi la funzione `clamp()` restituisce il valore inalterato: 450.0."
  },
  {
   "codice": "extends RefCounted

func run():
	var pos_x: float = 600.0
	return clamp(pos_x, 0.0, 500.0)
",
   "domanda": "Quanto vale il valore restituito da `run()`?",
   "spiegazione": "`pos_x` supera il limite massimo consentito (500.0). La funzione `clamp()` blocca il valore al limite superiore e restituisce 500.0."
  },
  {
   "codice": "extends RefCounted

func run():
	var move_left: bool = false
	var move_right: bool = true
	var direction: float = 0.0
	if move_left:
		direction -= 1.0
	if move_right:
		direction += 1.0
	return direction
",
   "domanda": "Quanto vale `direction` alla fine?",
   "spiegazione": "`move_left` è falso, quindi non viene sottratto nulla. `move_right` è vero, quindi viene aggiunto 1.0 a `direction`, che alla fine vale 1.0."
  },
  {
   "codice": "extends RefCounted

func run():
	var move_left: bool = true
	var move_right: bool = true
	var direction: float = 0.0
	if move_left:
		direction -= 1.0
	if move_right:
		direction += 1.0
	return direction
",
   "domanda": "Quanto vale `direction` alla fine?",
   "spiegazione": "Entrambe le condizioni sono vere: prima si sottrae 1.0 (portando `direction` a -1.0) e poi si aggiunge 1.0, azzerando il risultato finale che torna a 0.0."
  },
  {
   "codice": "extends RefCounted

func run():
	var position_x: float = 480.0
	var direction: float = 1.0
	var speed: float = 300.0
	var delta: float = 0.1
	position_x += direction * speed * delta
	return clamp(position_x, 0.0, 500.0)
",
   "domanda": "Quanto vale il valore restituito?",
   "spiegazione": "Il movimento calcolato è `1.0 * 300.0 * 0.1 = 30.0`. Sommato a `position_x` (480.0) si arriva a 510.0. Applicando `clamp()` con limite massimo a 500.0, il valore viene limitato a 500.0."
  }
 ]
}
